1	package api
2	
3	import (
4		"bufio"
5		"encoding/csv"
6		"errors"
7		"io"
8		"net/http"
9		"strings"
10	
11		"example.com/tally/internal/auth"
12		"example.com/tally/internal/store"
13	)
14	
15	// maxImportRows is the most data records one import takes.
16	const maxImportRows = 10000
17	
18	// metadataPrefix starts the header of a column that fills a metadata key ("metadata.plan").
19	const metadataPrefix = "metadata."
20	
21	// importColumns says where each field of a customer is in the file: -1 when the header has no such column.
22	type importColumns struct {
23		name, email, paymentMethod int
24		metadata                   []metadataColumn
25	}
26	
27	type metadataColumn struct {
28		key string
29		col int
30	}
31	
32	// importRow is a data record of an import, with the line it starts on and the first problem with it ("" when it has none).
33	type importRow struct {
34		line     int
35		customer store.NewCustomer
36		problem  string
37	}
38	
39	// rowError is one bad record in an invalid_rows answer.
40	type rowError struct {
41		Row  int    `json:"row"`
42		Code string `json:"error"`
43	}
44	
45	// importCustomers creates the customers listed in a CSV body: the first record is the header, then one record per customer.
46	// Every record is checked before anything is created, so a file with a bad record creates nothing. With ?dry_run=true it is
47	// only checked.
48	func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
49		cr := csv.NewReader(skipBOM(r.Body))
50		cr.FieldsPerRecord = -1 // checked below, after blank lines are skipped
51		head, _, err := nextRecord(cr)
52		if errors.Is(err, io.EOF) {
53			importError(w, http.StatusUnprocessableEntity, "invalid_header")
54			return
55		}
56		if err != nil {
57			importError(w, http.StatusBadRequest, "invalid_csv")
58			return
59		}
60		cols, ok := importHeader(head)
61		if !ok {
62			importError(w, http.StatusUnprocessableEntity, "invalid_header")
63			return
64		}
65	
66		var rows []importRow
67		seen := map[string]bool{} // lower-case emails of the records so far
68		for {
69			rec, line, err := nextRecord(cr)
70			if errors.Is(err, io.EOF) {
71				break
72			}
73			if err != nil || len(rec) != len(head) {
74				importError(w, http.StatusBadRequest, "invalid_csv")
75				return
76			}
77			if len(rows) == maxImportRows {
