114	// checkImportRecord checks one record like POST /v1/customers does, and returns the customer it describes with the first
115	// problem that applies ("" when there is none). seen holds the lower-case email addresses of the records before it.
116	func (s *Server) checkImportRecord(orgID string, rec []string, cols importColumns, seen map[string]bool) (store.NewCustomer, string) {
117		nc := store.NewCustomer{Name: strings.TrimSpace(rec[cols.name]), Email: strings.TrimSpace(rec[cols.email])}
118		if cols.paymentMethod >= 0 {
119			nc.DefaultPaymentMethod = strings.TrimSpace(rec[cols.paymentMethod])
120		}
121		for _, mc := range cols.metadata {
122			if v := strings.TrimSpace(rec[mc.col]); v != "" {
123				if nc.Metadata == nil {
124					nc.Metadata = map[string]string{}
125				}
126				nc.Metadata[mc.key] = v
127			}
128		}
129	
130		// An earlier record counts for its email address even when that record has another problem.
131		emailOK := store.ValidEmail(nc.Email)
132		key := strings.ToLower(nc.Email)
133		earlier := emailOK && seen[key]
134		if emailOK {
135			seen[key] = true
136		}
137		switch {
138		case nc.Name == "":
139			return nc, "missing_name"
140		case !emailOK:
141			return nc, "invalid_email"
142		case nc.DefaultPaymentMethod != "" && !strings.HasPrefix(nc.DefaultPaymentMethod, "pm_"):
143			return nc, "invalid_payment_method"
144		}
145		if _, ok := s.store.FindCustomerByEmail(orgID, nc.Email); ok {
146			return nc, "email_taken"
147		}
148		if earlier {
149			return nc, "duplicate_email"
150		}
151		return nc, ""
152	}
