154	// importHeader finds the columns of a header: name and email are required, and a column named "metadata.<key>" fills that
155	// metadata key. Names match ignoring case and surrounding spaces; the first column with a name is the one used.
156	func importHeader(head []string) (importColumns, bool) {
157		cols := importColumns{name: -1, email: -1, paymentMethod: -1}
158		keys := map[string]bool{}
159		for i, h := range head {
160			h = strings.TrimSpace(h)
161			switch strings.ToLower(h) {
162			case "name":
163				cols.name = firstColumn(cols.name, i)
164			case "email":
165				cols.email = firstColumn(cols.email, i)
166			case "default_payment_method":
167				cols.paymentMethod = firstColumn(cols.paymentMethod, i)
168			}
169			if len(h) > len(metadataPrefix) && strings.EqualFold(h[:len(metadataPrefix)], metadataPrefix) {
170				key := strings.TrimSpace(h[len(metadataPrefix):])
171				if key != "" && !keys[key] {
172					keys[key] = true
173					cols.metadata = append(cols.metadata, metadataColumn{key: key, col: i})
174				}
175			}
176		}
177		return cols, cols.name >= 0 && cols.email >= 0
178	}
179	
180	func firstColumn(cur, i int) int {
181		if cur < 0 {
182			return i
183		}
184		return cur
185	}
186	
187	// nextRecord returns the next record that is not blank, and the line it starts on. It returns io.EOF after the last one.
188	func nextRecord(cr *csv.Reader) ([]string, int, error) {
189		for {
190			rec, err := cr.Read()
191			if err != nil {
192				return nil, 0, err
193			}
194			if !blankRecord(rec) {
195				line, _ := cr.FieldPos(0)
196				return rec, line, nil
197			}
198		}
199	}
200	
201	func blankRecord(rec []string) bool {
202		for _, f := range rec {
203			if strings.TrimSpace(f) != "" {
204				return false
205			}
206		}
207		return true
208	}
209	
210	// skipBOM returns r without the UTF-8 byte order mark at its start, if it has one.
211	func skipBOM(r io.Reader) io.Reader {
212		br := bufio.NewReader(r)
213		if b, err := br.Peek(3); err == nil && string(b) == "\xef\xbb\xbf" {
214			_, _ = br.Discard(3)
215		}
216		return br
217	}
218	
219	// importError answers {"error": code}, the shape the import's errors have.
220	func importError(w http.ResponseWriter, status int, code string) {
221		writeJSON(w, status, map[string]string{"error": code})
222	}
